template <void (*Erase)(void*, node*)>
struct ref_set
{
  node* header;
  unsigned int count;
  unsigned int unused;

  ~ref_set()
  {
    if (count)
    {
      Erase(this, header->parent);
      header->left = header;
      header->parent = 0;
      header->right = header;
      count = 0;
    }
    arch_free(header);
  }
};

struct iterator
{
  node* current;

  void increment()
  {
    if (current->right)
    {
      current = current->right;
      while (current->left)
        current = current->left;
    }
    else
    {
      node* next = current->parent;
      while (current == next->right)
      {
        current = next;
        next = next->parent;
      }
      if (current->right != next)
        current = next;
    }
  }
};

struct instance_bank
{
  ref_set<erase_label> refs_by_label;
  ref_set<erase_ptr> refs_by_ptr;

  ~instance_bank();
};

instance_bank::~instance_bank()
{
  iterator i;
  for (i.current = refs_by_label.header->left;
       i.current != refs_by_label.header;
       i.increment())
  {
    ref_t* r = i.current->value;
    debug_print("WARNING: Unreleased instance.");
    delete r;
  }
}
